    "No direct brain or CSF measurement for the exact query molecule.",
    "Unbound brain-to-plasma concentration and P-gp efflux liability are not directly quantified.",
    "All key evidence is from rodent or imaging studies rather than human pharmacokinetic data."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C10"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "benzylpiperidine dimethoxy bicyclics"
    }
  ],
  "revision_action": "initial"
}

